function destination(id){return state?.channels?.find(c=>c.id===id)||state?.destinationMap?.[id]||{id,platform:platformNames[id]?id:'',name:platformNames[id]||'مقصد قبلی'};}
function destinationName(id){const c=destination(id),platform=platformNames[c.platform]||'';return c.name&&c.name!==platform?c.name+(platform?' · '+platform:''):platform||c.name;}
function receiptName(row){return row.channel_name?(row.channel_name+(platformNames[row.platform]&&row.channel_name!==platformNames[row.platform]?' · '+platformNames[row.platform]:'')):destinationName(row.channel_id);}
function destinationPlatform(id){return destination(id).platform;}
function platformLogo(id){const file={bale:'bale.png',rubika:'rubika.ico'}[id]||id+'.svg';return `<span class="platform-badge official-logo"><img src="/logos/${file}" alt="" width="28" height="28"></span>`;}
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.posts}"/></svg>`;}
function plainUi(value=''){
 const input=String(value);if(!/[\u0600-\u06ff]/.test(input))return input;
 const protectedText=[];
 const source=input.replace(/(?:https?:\/\/|www\.)[^\s<>"']+|[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g,part=>{protectedText.push(part);return '\u0000'+(protectedText.length-1)+'\u0000';});
 return source.replace(/پیام\u200cرسان/g,'پیامرسان').replace(/واتس\u200cاپ/g,'واتساپ').replace(/مسئول/g,'مسوول').replace(/[\u064B-\u065F\u0670]/g,'').replace(/\u200c/g,' ').replace(/[أإٱ]/g,'ا').replace(/ؤ/g,'و').replace(/ئ/g,'ی').replace(/ء/g,'').replace(/\.(?=\s|$)/g,'').replace(/\u0000(\d+)\u0000/g,(_,index)=>protectedText[Number(index)]);
}
function esc(value=''){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function number(value){return new Intl.NumberFormat('fa-IR').format(value);}
function activeTimeZone(){return timeZone(state?.settings?.timezone);}
function date(value,short=false){if(!value)return 'تعیین نشده';return new Intl.DateTimeFormat('fa-IR',{dateStyle:short?'short':'medium',...(short?{}:{timeStyle:'short'}),timeZone:activeTimeZone()}).format(new Date(value));}
function editable(){return !state?.capabilities?.needsBrand&&['admin','publisher','editor'].includes(state?.user.role);}
function postName(post){return post.library_title||post.title;}
function canRenamePost(post){return libraryState(post)==='active'&&editable()&&(state.user.role!=='editor'||post.author_id===state.user.id)&&(admin()||post.channels.every(id=>state.user.channels.includes(id)));}
function canEditPost(post){return libraryState(post)==='active'&&['draft','ready','archived'].includes(post.status)&&editable()&&(state.user.role!=='editor'||post.author_id===state.user.id)&&(admin()||post.channels.every(id=>state.user.channels.includes(id)));}
function canCopyPost(post){return !!post&&libraryState(post)!=='deleted'&&post.status!=='publishing'&&!post.publications?.some(row=>row.status==='sending')&&editable();}
function publisher(){return !state?.capabilities?.needsBrand&&['admin','publisher'].includes(state?.user.role);}
function admin(){return !state?.capabilities?.needsBrand&&state?.user.role==='admin';}
function toast(message){const box=document.querySelector('#toast');box.textContent=plainUi(message);box.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('show'),6500);}
async function api(url,options={}){const workspaceId=state?.workspace?.id||bootstrap?.workspace?.id;const headers={...(url!=='/api/bootstrap'&&workspaceId?{'X-Workspace-Id':workspaceId}:{}),'X-CSRF-Token':state?.csrf||bootstrap?.csrf||'',...options.headers};if(options.body&&!(options.body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch(url,{...options,headers,body:options.body instanceof FormData?options.body:options.body?JSON.stringify(options.body):undefined});const data=await response.json();if(!response.ok){if(response.status===401&&state){state=null;await init();}throw new Error(plainUi(data.error||'انجام درخواست ممکن نشد'));}return data;}
function field(name,label,value='',options={}){const {type='text',hint='',required=false,ltr=false,placeholder='',full=false}=options;return `<label class="field ${full?'full':''}"><span>${label}${required?' *':''}</span>${type==='textarea'?`<textarea name="${name}" rows="${options.rows||4}" ${required?'required':''} ${ltr?'class="ltr" dir="ltr"':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${ltr?'class="ltr" dir="ltr"':''} placeholder="${esc(placeholder)}" ${options.autocomplete||type==='password'?'autocomplete="'+(options.autocomplete||'new-password')+'"':''} ${options.min?`min="${options.min}"`:''} ${options.max?`max="${options.max}"`:''}>`}${hint?`<small>${hint}</small>`:''}</label>`;}
function assistedField(name,label,value='',options={}){if(!['topic','title','description','specs','cta','note','summary'].includes(name))return field(name,label,value,options);return '<div class="assisted-field '+(options.full?'full':'')+'">'+field(name,label,value,{...options,full:false})+'<button type="button" class="assist-button" data-action="text-assist" data-target="'+name+'" data-label="'+esc(label)+'">✦ کمک هوش مصنوعی</button></div>';}
function captionMarkup(body,entities=[],free=editor?.type==='free'){return richMarkup(body,[...(!free&&body?[{type:'bold',offset:0,length:body.split('\n')[0].length}]:[]),...entities]);}
function commonFields(){const f=editor.fields||{};
 if(editor.type==='free')return field('title','نام داخلی پیام (اختیاری)',postName(editor)||'',{full:true,hint:'فقط برای پیدا کردن پیام در کتابخانه؛ در پیام ارسالی درج نمی شود'})+richField('متن پیام',f.description||'',f.description_entities||[]);
 return (editor.library_title!=null?field('library_title','نام در کتابخانه',editor.library_title,{full:true,hint:'فقط نام داخل کتابخانه است و در متن ارسالی درج نمی شود'}):'')+assistedField('topic','موضوع / هدف پست',f.topic||'',{full:true,placeholder:'موضوع یا نکته ای که می خواهید مخاطب دریافت کند',hint:'برای برنامه ریزی و کمک هوش مصنوعی؛ خود این فیلد در کپشن چاپ نمی شود'})+assistedField('title','عنوان جذاب پست',editor.title||'',{full:true,required:true,placeholder:'خط اول کپشن زیر تصویر',hint:'در مقصد پشتیبانی شده بولد نمایش داده می شود'})+richField('توضیحات پست',f.description||'',f.description_entities||[]);
}
function phoneRow(phone={type:'phone',number:'',label:''}){return '<div class="phone-row"><label class="field"><span>نوع شماره</span><select data-phone-type aria-label="نوع شماره"><option value="phone" '+(phone.type==='phone'?'selected':'')+'>تلفن</option><option value="mobile" '+(phone.type==='mobile'?'selected':'')+'>موبایل</option></select></label><label class="field"><span>شماره تماس</span><input data-phone-number aria-label="شماره تماس" type="tel" dir="ltr" class="ltr" value="'+esc(phone.number)+'" placeholder="+989121234567"></label><label class="field"><span>عنوان شماره (اختیاری)</span><input data-phone-label aria-label="عنوان شماره" value="'+esc(phone.label)+'" placeholder="مثلا فروش"></label><button type="button" class="button danger small" data-action="remove-phone" aria-label="حذف شماره">حذف</button></div>';}
function contactsEditor(value={},post=false){const c=value||{};return '<section class="contacts-editor full" data-contact-editor><div class="contact-heading"><h3>شماره های تماس</h3><button type="button" class="button secondary small" data-action="add-phone">+ افزودن شماره</button></div><p class="help">تلفن یا موبایل را با کد شهر یا کشور وارد کنید امکان تماس با کلیک، به پشتیبانی پیامرسان و دستگاه مخاطب بستگی دارد</p><div data-phone-list>'+(c.phones||[]).map(phoneRow).join('')+'</div><details class="admin-contacts" open><summary>آیدی ادمین هر پیامرسان</summary><p class="help">در هر مقصد فقط آیدی ادمین همان پیامرسان درج می شود می توانید آیدی یا لینک گفت وگوی همان پیامرسان را وارد کنید</p><div class="form-grid">'+Object.entries(contactPlatforms).filter(([id])=>id!=='whatsapp').map(([id,label])=>'<label class="field"><span>ادمین '+label+'</span><input data-admin="'+id+'" aria-label="ادمین '+label+'" dir="ltr" class="ltr" value="'+esc(c.admins?.[id]||'')+'" placeholder="'+(id==='whatsapp'?'@username یا +989121234567':'@username')+'"></label>').join('')+'</div></details>'+((c.extra||'')?'<label class="field"><span>اطلاعات ارتباطی قبلی</span><textarea data-contact-extra aria-label="اطلاعات ارتباطی قبلی">'+esc(c.extra)+'</textarea><small>متن قبلی حفظ شده است؛ پس از انتقال به ردیف های بالا می توانید آن را پاک کنید</small></label>':'')+(post?'<button type="button" class="button secondary small" data-action="reset-contacts">استفاده از اطلاعات تنظیمات برند</button>':'')+'</section>';}
function collectContacts(form){const box=form.querySelector('[data-contact-editor]');return {phones:[...box.querySelectorAll('.phone-row')].map(row=>({type:row.querySelector('[data-phone-type]').value,number:row.querySelector('[data-phone-number]').value,label:row.querySelector('[data-phone-label]').value})),admins:Object.fromEntries([...box.querySelectorAll('[data-admin]')].map(input=>[input.dataset.admin,input.value])),extra:box.querySelector('[data-contact-extra]')?.value||''};}
function defaultContacts(){return {...(state.settings.contacts||{phones:[],admins:{}}),extra:state.settings.contacts?.extra||state.settings.contact||''};}
function editorContactFields(){const f=editor.fields||{},legacy=Object.hasOwn(f,'contact_override')&&!Object.hasOwn(f,'contact_config');return legacy?field('contact_override','اطلاعات ارتباطی قبلی این پست',f.contact_override,{type:'textarea',full:true}):contactsEditor(f.contact_config||defaultContacts(),true);}
function channelChecks(selected=[],name='channels',publishing=false){
 const rows=state.channels.map(c=>{const issue=publishing&&!c.publishing?.ready;return '<label class="check-row"><input type="checkbox" name="'+name+'" value="'+esc(c.id)+'" '+(selected.includes(c.id)?'checked':'')+' '+(issue&&!selected.includes(c.id)?'disabled':'')+'><span>'+esc(destinationName(c.id))+(issue?'<small class="destination-warning">'+esc(c.publishing?.message||'ابتدا اتصال این مقصد را تنظیم کنید')+'</small>':'')+'</span></label>';});
 for(const id of selected.filter(id=>!state.channels.some(c=>c.id===id)))rows.push('<label class="check-row"><input type="checkbox" name="'+name+'" value="'+esc(id)+'" checked><span>'+esc(destinationName(id))+'<small class="destination-warning">این مقصد دیگر در دسترس نیست برای ذخیره آن را از انتخاب بردارید</small></span></label>');
 return '<div class="checks">'+rows.join('')+'</div>';
}
function badge(post){const status=libraryState(post)==='active'?post.status:libraryState(post),tone={draft:'post-status-draft',ready:'post-status-ready',published:'post-status-published'}[status]||'';return `<span class="tag ${tone}">${status==='deleted'?'حذف شده':statusNames[status]||esc(status)}</span>`;}
function empty(title,description,button=true){return `<div class="empty"><div class="empty-art">${icon('posts')}</div><h3>${title}</h3><p>${description}</p>${button&&editable()?`<button class="button" data-action="create">${icon('plus')}ساخت اولین محتوا</button>`:''}</div>`;}
function navigate(view){if(view==='queue'){search='';view='posts/ready';}const target=({channels:'settings/channels',ai:'settings/ai',users:'settings/team',activity:'settings/activity'})[view]||view;if(location.hash==='#'+target){if(current==='settings'){const section=settingsRoute(target);if(section)settingsAccordions?.reveal(section);syncSidebar();return;}current=workspaceView();shell();}else location.hash=target;}
function workspaceView(){
 settingsTarget='';if(state?.capabilities?.needsBrand){history.replaceState(null,'','#settings');return 'settings';}
 let view=location.hash.slice(1)||'dashboard';if(view==='queue'){search='';view='posts/ready';history.replaceState(null,'','#posts/ready');}const alias={channels:'settings/channels',ai:'settings/ai',users:'settings/team',activity:'settings/activity',reports:'dashboard'};
 if(alias[view]){view=alias[view];history.replaceState(null,'','#'+view);}
 if(view==='posts'||view.startsWith('posts/')){const next=libraryRoute(view);if(filter!==next)selectedPosts.clear();filter=next;return 'posts';}
 if(view.startsWith('settings/')){settingsTarget=settingsRoute(view);if(settingsTarget==='team'&&!admin())settingsTarget='access';return 'settings';}
 return ['dashboard','posts','calendar','settings','editor'].includes(view)?view:'dashboard';
}
function settingsScope(){return JSON.stringify([state?.account?.id||state?.user?.id,state?.workspace?.id]);}
async function refresh(){const previous=state;state=await api('/api/state');if(previous?.workspace.id!==state.workspace.id||previous?.user.id!==state.user.id)selectedPosts.clear();if(previous?.workspace.id===state.workspace.id&&previous?.user.id===state.user.id&&previous.users)state.users=previous.users;await guidance.setContext({accountId:state.account?.id||state.user.id,workspaceId:state.workspace.id,sessionKey:state.csrf});}
function projectName(){return 'محتوان';}
function activeBrandName(){return state?.settings?.brand||state?.workspace?.name||projectName();}
function workspaceSelector(){return '<div class="workspace-selector">'+((state.workspaces||[]).length?'<div class="workspace-select-group"><span>برند فعال</span><div class="workspace-picker" id="workspace-control">'+workspacePickerMarkup(state.workspaces,state.workspace.id)+'</div></div>':'')+(state.capabilities?.canCreateBrands?'<button type="button" data-action="add-workspace" class="button secondary">'+icon('plus')+'افزودن برند یا شرکت</button>':'')+'</div>';}
function bindWorkspacePicker(){workspacePicker?.destroy();const control=document.querySelector('#workspace-control');workspacePicker=control?mountWorkspacePicker(control,{onSelect:switchWorkspace}):null;}

function publishingNotice(){return `<div class="banner" data-guidance-note="publishing-overview" role="status">${icon('pause')}<div><strong>انتشار فوری تلگرام، بله، روبیکا و ایتا فعال است</strong><br>هر مقصد به توکن و شناسه معتبر نیاز دارد؛ نتیجه ارسال هر پیامرسان جداگانه ثبت می شود</div>${admin()?'<a href="#settings/channels">تنظیم کانال ها</a>':''}</div>`;}
function sidebarNavigation(){
 const names={dashboard:'داشبورد',posts:'کتابخانه محتوا',calendar:'تقویم محتوا',settings:'تنظیمات'},section=settingsRoute(location.hash.slice(1));
 return navigationGroups({view:current,filter,section,canCreate:editable(),needsBrand:state.capabilities?.needsBrand}).map(group=>{
  const {key,children}=group,expanded=navExpanded===key,main=`<button type="button" data-action="${children.length?'toggle-subnav':'nav'}" ${children.length?'data-group="'+key+'" aria-controls="nav-'+key+'-submenu" aria-expanded="'+expanded+'"':'data-view="'+key+'"'} aria-label="${names[key]}" class="nav-main ${group.active?'active':''}" ${group.active?'aria-current="'+(children.length?'true':'page')+'"':''}>${icon(key==='dashboard'?'home':key)}<span class="nav-title">${names[key]}</span><span class="nav-title-compact" aria-hidden="true">${key==='posts'?'کتابخانه':key==='calendar'?'تقویم':names[key]}</span>${children.length?'<svg class="icon nav-submenu-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>':''}</button>`;
  const create=key==='posts'?`<button type="button" class="nav-create ${current==='editor'?'active':''}" data-action="create" aria-label="محتوای جدید" title="${editable()?'محتوای جدید':'دسترسی ساخت محتوا ندارید'}" ${editable()?'':'disabled'}>${icon('plus')}</button>`:'';
  if(!children.length)return '<div class="nav-parent">'+main+'</div>';
  return `<div class="nav-group" data-nav-group="${key}" data-expanded="${expanded}"><div class="nav-parent">${main}</div><div id="nav-${key}-submenu" class="nav-submenu" role="group" aria-label="میانبرهای ${names[key]}" ${expanded?'':'inert'}><div class="nav-submenu-clip"><div class="nav-submenu-heading"><strong>${names[key]}</strong><button type="button" data-action="close-subnav" aria-label="بستن میانبرها"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m6 6 12 12M6 18 18 6"/></svg></button></div><div class="nav-submenu-items">${children.map(item=>`<button type="button" data-action="${item.action||'nav'}" ${item.view?'data-view="'+item.view+'"':''} class="${item.active?'active':''}" ${item.active?'aria-current="page"':''}>${item.label}</button>`).join('')}</div></div></div></div>${create}`;
 }).join('');
}
function bindSidebar(){navigation?.destroy();const sidebar=root.querySelector('.sidebar');sidebar.querySelector('#workspace-nav').dataset.limited=String(!!state.capabilities?.needsBrand);navigation=mountNavigation(sidebar,{onSubmenuChange:key=>{navExpanded=key;}});}
function syncSidebar(){root.querySelector('#workspace-nav').innerHTML=sidebarNavigation();bindSidebar();}
function shell(){
 contentCalendar?.destroy();contentCalendar=null;
 editorDates?.destroy();editorDates=null;
 settingsAccordions?.destroy();settingsAccordions=null;
 previewLayout?.destroy();previewLayout=null;
 navigation?.destroy();navigation=null;
 const sidebarScroll=window.matchMedia('(min-width:1025px)').matches?(root.querySelector('.sidebar')?.scrollTop||0):0;
 workspacePicker?.destroy();workspacePicker=null;
 document.title=projectName()+' | مدیریت انتشار';
 descriptionEditor=null;
 const names={dashboard:'داشبورد',posts:'کتابخانه محتوا',calendar:'تقویم محتوا',activity:'تاریخچه تغییرات',settings:'تنظیمات',editor:editor?.id?'ویرایش محتوا':'محتوای جدید'};
 if(navExpanded===null)navExpanded=current==='editor'?'posts':['posts','settings'].includes(current)?current:'';
 root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${brandLogo()}<strong class="active-brand-name" title="${esc(activeBrandName())}">${esc(activeBrandName())}</strong></div><button type="button" class="nav-toggle" data-action="toggle-nav" aria-controls="workspace-nav" aria-expanded="false" aria-label="باز و بسته کردن منو"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path class="menu-line top" d="M4 6h16"/><path class="menu-line middle" d="M4 12h16"/><path class="menu-line bottom" d="M4 18h16"/></svg><span>منو</span></button><div class="nav-label">فضای کار</div><button type="button" class="nav-sheet-backdrop" data-action="close-subnav" aria-label="بستن پنل میانبرها" tabindex="-1"></button><div class="nav-panel"><div class="nav-clip"><nav id="workspace-nav" class="nav" aria-label="بخش های پنل"></nav></div></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">${esc(activeBrandName())}</div><h1>${names[current]||'اتاق محتوا'}</h1></div><div class="top-actions"><span class="date">${date(new Date(),true)}</span>${editable()&&current!=='editor'?`<button class="button" data-action="create">${icon('plus')}محتوای جدید</button>`:''}<button class="button ghost" data-action="logout" aria-label="خروج" title="خروج">${icon('logout')}</button></div></header>${state.capabilities?.needsBrand?'':publishingNotice()}<div id="view"></div></main></div>`;
 root.querySelector('#workspace-nav').innerHTML=sidebarNavigation();root.querySelector('.sidebar').scrollTop=sidebarScroll;bindSidebar();
 const view=document.querySelector('#view');
 if(current==='dashboard')view.innerHTML=dashboard()+dashboardReports();
 if(current==='posts'){view.innerHTML=contentLibrary();bindLibrary();}
 if(current==='calendar'){
  const scope=settingsScope();contentCalendar=mountCalendar(view,{timeZone:activeTimeZone(),canChangeZone:admin(),initial:calendarState,onState:value=>{calendarState=value;},load:(from,to)=>api('/api/calendar?'+new URLSearchParams({from,to})),openQueue:()=>navigate('queue'),openPost:async id=>{
   const result=await api('/api/posts/'+id);if(scope!==settingsScope()||current!=='calendar')return;
   state.mediaMap={...state.mediaMap,...result.mediaMap};state.posts=state.posts.filter(p=>p.id!==id);state.posts.push(result.post);await inspectPost(result.post);
  }});
 }
 if(current==='editor'){view.innerHTML=editorView();bindEditor();}
 if(current==='settings'){
  view.innerHTML=workspaceSettingsView()+(!state.capabilities?.needsBrand?connectionSettingsView()+accessSettingsView():'')+accountSettingsView();
  bindWorkspacePicker();bindBrandLogo();bindChannels();settingsAccordions=mountSettingsAccordions(view,{scope:settingsScope()});
  if(settingsTarget){settingsAccordions.reveal(settingsTarget);settingsTarget='';}
  if(admin())loadUsers().catch(error=>toast(error.message));
 }
}
function dashboard(){const totals=state.librarySummary||librarySummary(state.posts);
 const posts=state.posts.filter(p=>libraryState(p)==='active');
 return `<div class="stats">${[['محتوای ثبت شده',totals.active,'در فضای کاری قابل دسترس شما','posts'],['آماده انتشار',totals.ready,'در انتظار زمان انتشار یا ارسال دستی','queue'],['پیش نویس ها',totals.draft,'قابل تکمیل و ویرایش','book'],['پیام های منتشر شده',state.publicationCount,'هر پیام یک بار؛ بدون موارد حذف شده','channels']].map(([label,value,hint,ico])=>`<div class="stat">${icon(ico)}<span class="stat-label">${label}</span><strong>${number(value)}</strong><small>${hint}</small></div>`).join('')}</div><div class="grid-main"><div><section class="panel"><div class="panel-head"><h2>آخرین محتواها</h2><button class="button ghost" data-action="nav" data-view="posts">همه محتواها ${icon('arrow')}</button></div>${posts.length?postRows(posts.slice(0,5)):empty('اولین محتوای شما از اینجا شروع می شود','نوع محتوا را انتخاب کنید، اطلاعات و تصویر را وارد کنید و پیش نمایش نهایی را ببینید')}</section><section class="panel section-gap" data-guidance-note="dashboard-start"><div class="panel-head"><h2>برای شروع آماده شوید</h2><span class="tag">گام به گام</span></div><div class="panel-body"><ol class="steps"><li><div><strong>اطلاعات ثابت برند را ثبت کنید</strong><small>نام برند، راه های ارتباطی و واحد قیمت فقط یک بار وارد می شوند</small></div></li><li><div><strong>یک محتوا بسازید و پیش نمایش را ببینید</strong><small>پیام آزاد، محصول، اعتمادسازی، لیست قیمت یا مطلب آموزشی</small></div></li><li><div><strong>اعضای تیم و دسترسی کانال ها را تعریف کنید</strong><small>نقش تولیدکننده، مسوول انتشار یا مشاهده گر</small></div></li><li><div><strong>کانال ها و مسیر شبکه را تنظیم کنید</strong><small>مسیر اینترنت سیستم یا پروکسی هر مقصد را انتخاب کنید؛ برای ارسال، توکن و شناسه کانال را ثبت کنید</small></div></li></ol></div></section></div><div class="side-panels"><section class="panel"><div class="panel-head"><h2>وضعیت کانال ها</h2><span class="tiny">${number(state.channels.length)} مقصد</span></div><div class="panel-body">${state.channels.map(c=>`<div class="channel-row">${platformLogo(c.platform)}<div class="text">${esc(destinationName(c.id))}<small>${c.route==='proxy'?'پروکسی جداگانه':'اینترنت سیستم / VPN'}</small></div><span class="tag ${c.network_status==='reachable'?'green':''}">${networkLabel(c)}</span></div>`).join('')}<div class="help">پاسخ شبکه به تنهایی به معنی اتصال انتشار نیست</div></div></section></div></div>`;
}
function canPublishPost(post){return libraryState(post)==='active'&&publisher()&&['draft','ready','partial','uncertain'].includes(post.status)&&(!['partial','uncertain'].includes(post.status)||post.publications?.some(row=>['failed','blocked'].includes(row.status)))&&(admin()||post.channels.every(id=>state.user.channels.includes(id)));}
async function showPublicationResults(postId){const scope=settingsScope();await openPublicationReport({postId,api,modalRoot,esc,number,date,writable:publisher(),isCurrent:()=>scope===settingsScope(),setBusy:value=>libraryActionInFlight=value,onChange:async()=>{await refresh();if(scope===settingsScope()&&current!=='editor')shell();}});}
async function publishSavedPost(id,version){if(publishingInFlight)throw new Error('انتشار دیگری در حال انجام است؛ منتظر نتیجه بمانید');publishingInFlight=true;const actor=state.user.id;toast('در حال ارسال؛ نتیجه هر مقصد ثبت می شود…');try{const result=await api('/api/posts/'+id+'/publish',{method:'POST',body:{version}});if(state?.user.id===actor){await refresh();if(current!=='editor')shell();await showPublicationResults(id);toast('ارسال تاییدشده: '+number(result.sent)+' از '+number(result.total)+' مقصد');}return result;}catch(error){if(state?.user.id===actor){try{await refresh();if(current!=='editor')shell();}catch{}}throw error;}finally{publishingInFlight=false;document.querySelectorAll('[data-action="publish-post"]').forEach(button=>button.disabled=false);}}
function postPublishActions(p){
 const queue=p.status==='draft'&&publisher()&&canEditPost(p),publish=canPublishPost(p);
 if(!queue&&!publish)return '';
 return `<span class="row-publish-actions">${queue?`<button class="button small" data-action="ready" data-id="${p.id}">ارسال به صف</button>`:''}${publish?`<button class="button small publish-now" data-action="publish-post" data-id="${p.id}" ${publishingInFlight?'disabled':''}>${p.status==='partial'?'ارسال مقصدهای ناموفق':'انتشار فوری'}</button>`:''}</span>`;
}
function libraryButtons(post){
 if(!canManageLibrary(post,state.user))return '';
 const placement=libraryState(post),button=(action,label,cls='secondary')=>`<button type="button" class="button ${cls} small" data-action="library-${action}" data-id="${post.id}">${label}</button>`;
 if(placement==='deleted')return button('restore','بازگردانی');
 return (placement==='archived'?button('restore','خروج از بایگانی'):button('archive','بایگانی'))+button('delete','حذف','danger');
}
function scheduleSummary(post){
 const job=post.schedule;
 if(job?.state==='queued')return '<p class="schedule-state">ارسال خودکار نسخه ذخیره شده: '+date(job.run_at)+'</p>';
 if(job?.state==='running')return '<p class="schedule-state">ارسال خودکار در حال انجام است</p>';
 if(job?.state==='failed')return '<p class="schedule-state schedule-error">'+esc(plainUi(job.message))+'</p>';
 if(post.status==='ready'&&post.scheduled_at&&job?.state!=='completed')return '<p class="schedule-state">ارسال دستی است برای فعال کردن ارسال خودکار، به پیش نویس برگردانید و با زمان آینده دوباره به صف بفرستید</p>';
 return '';
}
function deliverySummary(post){
 if(!post.publications?.length)return '';
 const statuses={sent:{tone:'success',label:'ارسال شد',mark:icon('check')},failed:{tone:'failure',label:'ناموفق',mark:'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg>'},blocked:{tone:'failure',label:'ارسال نشد',mark:'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg>'},unknown:{tone:'warning',label:'نتیجه نامشخص',mark:'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 2 21h20ZM12 9v5m0 3v.1"/></svg>'},sending:{tone:'pending',label:'در حال ارسال',mark:icon('clock')}};
 return '<div class="delivery-summary" role="group" aria-label="وضعیت ارسال به مقصدها">'+post.publications.map(row=>{
  const status=statuses[row.status]||{...statuses.unknown,label:'نیازمند بررسی'},platform=row.platform||destinationPlatform(row.channel_id);
  const label=receiptName(row)+' · '+(row.confirmation==='manual'?'تایید دستی کاربر':status.label);
  return '<button type="button" class="delivery-badge '+status.tone+'" data-action="inspect" data-id="'+esc(post.id)+'" aria-label="'+esc(label)+'" title="'+esc(label)+'">'+(['telegram','bale','rubika','eitaa'].includes(platform)?platformLogo(platform):icon('channels'))+'<span class="delivery-status" aria-hidden="true">'+status.mark+'</span></button>';
 }).join('')+'</div>';
}
function postThumbnail(post){
 const media=post.remote_media??publicationMedia(post),image=media.find(id=>state.mediaMap[id]?.mime?.startsWith('image/')),textOnly=!media.length;
 return '<span class="type-icon post-thumbnail'+(textOnly?' post-text-thumbnail':'')+'"'+(textOnly?' role="img" aria-label="پیام متنی"':'')+'>'+icon(textOnly?'text':'camera')+(image?'<img data-post-thumbnail src="/media/'+esc(image)+'" alt="تصویر پست '+esc(postName(post))+'" loading="lazy" decoding="async">':'')+'</span>';
}
function postRows(posts){const selectable=current==='posts';return `<div class="content-list">${posts.map(p=>`<article class="content-row ${selectedPosts.has(p.id)?'is-selected':''}" data-post-id="${p.id}">${selectable&&canManageLibrary(p,state.user)?`<label class="post-select"><input type="checkbox" data-select-post="${p.id}" aria-label="انتخاب ${esc(postName(p))}" ${selectedPosts.has(p.id)?'checked':''}></label>`:''}${postThumbnail(p)}<div class="grow"><h3>${esc(postName(p))}</h3><p><span>${p.publisher_names?.length?'ناشر: '+esc(p.publisher_names.join('، ')):'سازنده: '+esc(p.author_name||state.user.name)}</span><span title="آخرین تغییر">${date(p.updated_at)}</span></p>${scheduleSummary(p)}${deliverySummary(p)}</div>${badge(p)}<div class="row-actions"><button class="button secondary small" data-action="inspect" data-id="${p.id}">جزئیات</button>${libraryButtons(p)}${p.status==='ready'&&publisher()&&canEditPost(p)?`<button class="button secondary small" data-action="draft" data-id="${p.id}">بازگشت به پیش نویس</button>`:''}${postPublishActions(p)}</div></article>`).join('')}</div>`;}
function contentLibrary(){return `<div class="toolbar library-toolbar"><input id="search" type="search" aria-label="جست وجوی محتوا" placeholder="جست وجو در عنوان محتوا…" value="${esc(search)}"><div class="library-tools"><div class="filters library-filters" role="group" aria-label="فیلتر وضعیت محتوا">${[['draft','پیش نویس'],['ready','صف انتشار'],['published','منتشر شده']].map(([key,label])=>`<button type="button" class="filter ${filter===key?'active':''}" aria-pressed="${filter===key}" title="${filter===key?'نمایش همه محتواها':'نمایش '+label}" data-action="filter" data-filter="${key}">${label}</button>`).join('')}</div>${(state.librarySummary||librarySummary(state.posts)).attention||filter==='attention'?`<button type="button" class="filter attention-filter ${filter==='attention'?'active':''}" data-action="filter" data-filter="attention" aria-pressed="${filter==='attention'}">نیازمند بررسی ${number((state.librarySummary||librarySummary(state.posts)).attention)}</button>`:''}<div class="library-utilities" role="group" aria-label="ابزارهای کتابخانه"><a class="library-icon" href="/api/export" aria-label="خروجی CSV" data-tooltip="خروجی CSV">${icon('download')}</a>${[['archived','archive','بایگانی'],['deleted','trash','سطل زباله']].map(([key,ico,label])=>`<button type="button" class="library-icon ${filter===key?'active':''}" aria-label="${label}" aria-pressed="${filter===key}" data-tooltip="${filter===key?'نمایش همه محتواها':label}" data-action="filter" data-filter="${key}">${icon(ico)}</button>`).join('')}</div></div></div>${state.postsTruncated?'<p class="status-line">فهرست به ۱۰۰۰ محتوای اخیر محدود است آمار داشبورد شامل همه محتواهای مجاز شماست</p>':''}<div id="library-bulk"></div><section class="panel" id="post-list"></section>`;}
function renamePostModal(post){modalRoot.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="rename-heading"><h2 id="rename-heading">تغییر نام داخلی</h2><form id="rename-post-form" data-id="${post.id}" data-version="${post.version}" data-previous="${esc(JSON.stringify(post.library_title??null))}"><label class="field"><span>نام در کتابخانه</span><input name="title" required maxlength="240" value="${esc(postName(post))}"></label><p class="help">فقط نام داخل پنل تغییر می کند؛ متن، نسخه و نتیجه ارسال در کانال ها حفظ می شود</p><div id="post-action-error"></div><div class="modal-actions"><button class="button" type="submit">ذخیره نام</button><button class="button secondary" type="button" data-action="close-modal">انصراف</button></div></form></div>`;document.querySelector('#rename-post-form input').focus();}
function copyPostModal(value){
 const posts=Array.isArray(value)?value:[value];if(!posts.length||posts.some(post=>!canCopyPost(post)))throw new Error('محتوای انتخاب شده برای کپی در دسترس نیست');
 copyRequest={scope:settingsScope(),posts:posts.map(({id,version,library_revision=0,control_revision=0,library_title=null})=>({id,version,library_revision,control_revision,library_title}))};
 modalRoot.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="copy-heading"><h2 id="copy-heading">کپی و بازنشر${posts.length>1?' '+number(posts.length)+' محتوا':''}</h2><ul class="library-action-names">${posts.slice(0,3).map(post=>'<li>'+esc(postName(post))+'</li>').join('')}</ul><p class="help">از هر محتوا یک پیش نویس مستقل با پسوند «(کپی)» ساخته می شود نام آن در کتابخانه قابل ویرایش است؛ ارسال پس از بررسی شما انجام می شود</p><form id="copy-post-form"><h3>مقصدهای ارسال جدید</h3><div class="copy-channel-selection"><label class="check-row"><input type="checkbox" data-select-all-channels><span>انتخاب همه کانال ها</span></label>${channelChecks([])}</div><p class="help">زمان انتشار قبلی پاک می شود اعتبار قیمت قبلی حفظ می شود؛ در صورت انقضا آن را بررسی و اصلاح کنید</p><div id="post-action-error" role="alert"></div><div class="modal-actions"><button class="button" type="submit">${posts.length===1?'ساخت کپی و ادامه':'ساخت کپی ها'}</button><button class="button secondary" type="button" data-action="close-modal">انصراف</button></div></form></div>`;
 bindChannelSelection(modalRoot.querySelector('#copy-post-form'));
}
async function inspectPost(post,{edit=false}={}){
 if(!post)throw Error('محتوا دیگر در دسترس نیست');
     if(!canEditPost(post)||post.publications?.length&&!edit){modalRoot.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><h2>${esc(postName(post))}</h2>${scheduleSummary(post)}<div class="${(post.publication_media_ids?.length||0)>1?'preview-album':''}">${previewMediaMarkup(post.remote_media||publicationMedia(post))}</div><div class="preview-message">${captionMarkup(post.remote_body!=null?appendContacts(post.remote_body,post.type==='free'?undefined:post.fields?.contact_config,destinationPlatform(post.channels[0])).body:post.delivery?.caption||post.delivery?.text||post.body,post.remote_entities||post.body_entities||[],post.type==='free')}</div><div class="modal-actions">${post.publications?.some(row=>row.status==='sent')&&!post.deleted_at?`<button class="button secondary" data-action="remote-controls" data-id="${post.id}">مدیریت پیام و آمار</button>`:''}${post.publications?.length?`<button class="button secondary" data-action="publication-results" data-id="${post.id}">نتیجه ارسال</button>`:''}${canEditPost(post)?`<button class="button secondary" data-action="edit-post" data-id="${post.id}">ویرایش محتوا</button>`:''}${libraryButtons(post)}${canRenamePost(post)?`<button class="button secondary" data-action="rename-post" data-id="${post.id}">تغییر نام داخلی</button>`:''}${canCopyPost(post)?`<button class="button" data-action="copy-post" data-id="${post.id}">کپی و ارسال مجدد</button>`:''}<button class="button secondary" data-action="close-modal">بستن</button></div></div>`;return;}
     editor=structuredClone(post);editor.signature=null;navigate('editor');return;
}
function libraryPosts(){return filterLibrary(state.posts,{search,filter});}
function updateBulkSelection(){
 const host=document.querySelector('#library-bulk');if(!host)return;
 const available=libraryPosts().filter(p=>canManageLibrary(p,state.user)),ids=new Set(available.map(p=>p.id));
 selectedPosts=new Set([...selectedPosts].filter(id=>ids.has(id)));
 host.innerHTML=editable()&&available.length?`<div class="bulk-actions" aria-label="مدیریت گروهی محتوا"><label class="check-row"><input type="checkbox" id="select-visible-posts" aria-label="انتخاب همه پیام های این فهرست" ${selectedPosts.size===available.length?'checked':''}><span>انتخاب همه</span></label><span class="selection-count ${selectedPosts.size?'':'hidden'}" role="status">${number(selectedPosts.size)} انتخاب شده</span><div class="bulk-buttons ${selectedPosts.size?'':'hidden'}">${filter!=='deleted'?'<button type="button" class="button secondary small" data-action="library-copy">کپی و بازنشر</button>':''}${filter==='deleted'||filter==='archived'?'<button type="button" class="button secondary small" data-action="library-restore" '+(!selectedPosts.size?'disabled':'')+'>بازگردانی گروهی</button>':'<button type="button" class="button secondary small" data-action="library-archive" '+(!selectedPosts.size?'disabled':'')+'>بایگانی گروهی</button>'}${filter!=='deleted'?'<button type="button" class="button danger small" data-action="library-delete" '+(!selectedPosts.size?'disabled':'')+'>حذف گروهی</button>':''}${selectedPosts.size?'<button type="button" class="button ghost small" data-action="clear-selection">لغو انتخاب</button>':''}</div></div>`:'';
 const all=host.querySelector('#select-visible-posts');if(all)all.indeterminate=selectedPosts.size>0&&selectedPosts.size<available.length;
 document.querySelectorAll('[data-select-post]').forEach(input=>{input.checked=selectedPosts.has(input.dataset.selectPost);input.closest('.content-row').classList.toggle('is-selected',input.checked);});
}
function drawLibrary(){const posts=libraryPosts();document.querySelector('#post-list').innerHTML=posts.length?postRows(posts):empty(filter==='deleted'?'محتوای حذف شده نداریم':filter==='archived'?'بایگانی هنوز خالی است':'محتوایی برای نمایش نداریم','فیلتر یا جست وجو را تغییر دهید',!['deleted','archived'].includes(filter));updateBulkSelection();}
function bindLibrary(){drawLibrary();document.querySelector('#search').addEventListener('input',event=>{search=event.target.value;selectedPosts.clear();drawLibrary();});}
function openLibraryAction(action,ids){
 if(mediaUploadInFlight){toast('ابتدا منتظر پایان بارگذاری فایل ها بمانید');return;}
 if(libraryActionInFlight||editorSubmitInFlight||publishingInFlight)return;
 const posts=state.posts.filter(post=>ids.includes(post.id));if(!posts.length||posts.some(post=>!canManageLibrary(post,state.user)))throw new Error('اجازه انجام این عملیات را ندارید یا ارسال در حال انجام است');
 const labels={delete:'حذف',archive:'بایگانی',restore:'بازگردانی'},label=labels[action];
 libraryRequest={action,scope:settingsScope(),route:location.hash,posts:posts.map(({id,version,library_revision=0})=>({id,version,library_revision})),fromEditor:current==='editor'};
 modalRoot.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="library-action-title"><h2 id="library-action-title">${label} ${number(posts.length)} محتوا</h2><ul class="library-action-names">${posts.slice(0,3).map(post=>'<li>'+esc(postName(post))+'</li>').join('')}</ul><p>${action==='delete'?'فقط از کتابخانه پنل حذف میشود و از فیلتر حذف شده ها قابل بازیابی است پیام های کانال ها باقی میمانند':action==='archive'?'محتوا به بایگانی منتقل میشود پیام ها و نتیجه ارسال در کانال ها حفظ میشوند':'محتوا به فهرست قبلی برمیگردد محتوای بایگانی شده در بایگانی باقی میماند'}</p>${posts.some(post=>post.status==='ready')?'<p>محتوای داخل صف به پیش نویس برمیگردد و برای ورود دوباره به صف باید بررسی شود</p>':''}${current==='editor'?'<p>این عملیات روی نسخه ذخیره شده انجام میشود تغییرات ذخیره نشده این صفحه کنار گذاشته میشود</p>':''}<form id="library-action-form"><div id="post-action-error" role="alert"></div><div class="modal-actions"><button type="submit" class="button ${action==='delete'?'danger':''}">${label}</button><button type="button" class="button secondary" data-action="close-modal">انصراف</button></div></form></div>`;
 modalRoot.querySelector('[data-action="close-modal"]').focus();
}

function localInput(iso){return localDateTime(iso,activeTimeZone());}
function utc(value,previous){return value&&previous&&value===localInput(previous)?previous:zonedToUtc(value,activeTimeZone());}
function typeFields(){const f=editor.fields||{};if(editor.type==='free')return '';
 if(editor.type==='stock')return `${assistedField('brand','برند محصول',f.brand,{required:true,placeholder:'نام سازنده'})}${assistedField('model','مدل دقیق',f.model,{required:true,ltr:true,placeholder:'مدل یا Part Number'})}${assistedField('condition','وضعیت کالا',f.condition,{placeholder:'مثلا نو یا کارکرده'})}${assistedField('price','قیمت',f.price,{ltr:true,placeholder:'بدون قیمت بگذارید تا «استعلام» درج شود'})}${assistedField('warranty','شرایط فروش یا گارانتی',f.warranty,{full:true})}${assistedField('url','لینک صفحه محصول',f.url,{ltr:true,type:'url',full:true})}`;
 if(editor.type==='proof')return `<label class="field full"><span>مرحله واقعی کار *</span><select name="stage">${[['preparing','آماده سازی سفارش'],['shipped','ارسال شده'],['delivered','تحویل شده'],['other','سایر رویدادهای برند']].map(([value,label])=>`<option value="${value}" ${f.stage===value?'selected':''}>${label}</option>`).join('')}</select></label>${assistedField('event','چه اتفاقی افتاده است؟',f.event,{type:'textarea',required:true,full:true,placeholder:'شرح کوتاه و واقعی؛ ارسال شدن را با تحویل شدن یکی نگیرید'})}${assistedField('note','توضیح تکمیلی',f.note,{type:'textarea',full:true})}`;
 if(editor.type==='prices')return `${assistedField('rows','ردیف های محصولات',f.rows,{type:'textarea',required:true,full:true,rows:8,placeholder:'برند | مدل | قیمت | انبار ما\nبرند | مدل | قیمت | تامین',hint:'هر محصول یک خط؛ چهار ستون با علامت | جدا شوند وضعیت فقط «انبار ما» یا «تامین» باشد'})}`;
 return `${assistedField('source','آدرس منبع',f.source,{type:'url',ltr:true,required:true,full:true})}${assistedField('summary','متن یا نکات تاییدشده منبع',f.summary,{type:'textarea',required:true,full:true,rows:7,placeholder:'نکاتی که باید در پست منتشر شوند'})}${assistedField('note','توضیح یا نکته برند شما',f.note,{type:'textarea',full:true})}`;
}
function editorSection(key,title,body,{hint='',grid=false}={}){
 return `<section class="panel section-gap editor-section" data-editor-accordion="${key}" aria-labelledby="editor-${key}-title"><div class="panel-head"><h2 id="editor-${key}-title">${title}</h2>${hint?'<span class="tiny" data-help-note>'+hint+'</span>':''}</div><div class="panel-body">${grid?'<div class="form-grid">'+body+'</div>':body}</div></section>`;
}
function newEditor(){return {type:'free',title:'',fields:{},channels:[],media:[],body:'',body_mode:'generated'};}
