function mountPreviewScroll(){
 const preview=document.querySelector('.editor-layout>.preview'),main=document.querySelector('.main');
 if(!preview||!main)return null;
 const controller=new AbortController();let frame=0;
 function update(){
  frame=0;
  const style=getComputedStyle(preview);
  if(style.position!=='sticky'){preview.style.removeProperty('--preview-height');return;}
  const gap=parseFloat(style.top)||20,mainBounds=main.getBoundingClientRect(),paddingTop=parseFloat(getComputedStyle(main).paddingTop)||0;
  const top=Math.max(preview.getBoundingClientRect().top,mainBounds.top+main.clientTop+paddingTop+gap);
  const bottom=Math.min(mainBounds.bottom-gap,window.innerHeight-gap,preview.parentElement.getBoundingClientRect().bottom);
  const height=Math.max(90,Math.floor(bottom-top)),value=height+'px';
  if(preview.style.getPropertyValue('--preview-height')!==value)preview.style.setProperty('--preview-height',value);
 }
 function schedule(){if(!frame)frame=requestAnimationFrame(update);}
 main.addEventListener('scroll',schedule,{passive:true,signal:controller.signal});
 window.addEventListener('resize',schedule,{passive:true,signal:controller.signal});
 const observer=new ResizeObserver(schedule);
 for(const element of [main,document.querySelector('.editor-layout>div'),document.querySelector('.topbar'),document.querySelector('.main>.banner')])if(element)observer.observe(element);
 update();
 return {destroy(){controller.abort();observer.disconnect();if(frame)cancelAnimationFrame(frame);}};
}

