function targetInput(target){return target==='caption'?{get value(){return editor.body||'';}}:document.querySelector('#editor-form [name="'+target+'"]');}
function openTextAssistant(target,label){const input=targetInput(target);if(!input)return;const data=collectEditor();textAssistant={target,label,original:input.value,context:signatureOf(data)};modalRoot.innerHTML='<div class="modal text-assist-modal" role="dialog" aria-modal="true" aria-labelledby="assist-title"><h2 id="assist-title">کمک هوش مصنوعی: '+esc(label)+'</h2><p class="help">می توانید از حساب متصل شده تولید متن بگیرید یا پرامپت را در ChatGPT کپی کنید پیشنهاد پس از بررسی شما فقط روی همین بخش اعمال می شود</p><label class="field"><span>نوع کمک</span><select id="assist-intent"><option value="suggest">نوشتن پیشنهاد جدید</option><option value="rewrite">بازنویسی متن موجود</option><option value="shorten">کوتاه تر کردن</option></select></label><label class="field"><span>دستور شما یا متن منبع تکمیلی</span><textarea id="assist-instructions" rows="3" placeholder="لحن، نکات لازم یا مشخصات مستند را بنویسید"></textarea></label><div class="checks">'+(state.ai?.canGenerate?'<button type="button" class="button small" data-action="assist-generate">تولید با حساب ChatGPT</button>':'<button type="button" class="button secondary small" data-action="ai-open">اتصال حساب ChatGPT</button>')+'<button type="button" class="button secondary small" data-action="assist-build">آماده کردن پرامپت</button><button type="button" class="button secondary small" data-action="assist-copy">کپی پرامپت برای ChatGPT</button></div><label class="field section-gap"><span>پرامپت آماده</span><textarea id="assist-prompt" readonly rows="5"></textarea></label><label class="field"><span>پیشنهاد دریافتی از هوش مصنوعی</span><textarea id="assist-result" rows="4" placeholder="پاسخ ChatGPT را اینجا بچسبانید؛ پیش از اعمال قابل ویرایش است"></textarea></label><div id="assist-error"></div><div class="modal-actions"><button type="button" class="button" data-action="assist-apply">اعمال فقط روی این بخش</button><button type="button" class="button secondary" data-action="close-modal">انصراف</button></div></div>';document.querySelector('#assist-instructions').focus();}
async function prepareTextAssistant(copy=false){const data=collectEditor();const result=await api('/api/text-assist/prompt',{method:'POST',body:{...data,target:textAssistant.target,current:targetInput(textAssistant.target).value,intent:document.querySelector('#assist-intent').value,instructions:document.querySelector('#assist-instructions').value}});document.querySelector('#assist-prompt').value=result.prompt;if(copy){await navigator.clipboard.writeText(result.prompt);toast('پرامپت کپی شد پاسخ را از ChatGPT در بخش پیشنهاد وارد کنید');}}
function applyTextSuggestion(){const input=targetInput(textAssistant.target),value=document.querySelector('#assist-result').value.trim();const error=document.querySelector('#assist-error');if(!value){error.innerHTML='<div class="error">ابتدا پیشنهاد را وارد کنید</div>';return;}if(input.value!==textAssistant.original){error.innerHTML='<div class="error">این بخش در این فاصله تغییر کرده است؛ کمک را دوباره باز کنید تا متن تازه بازنویسی نشود</div>';return;}if(textAssistant.target==='title'&&(value.includes('\n')||value.length>250)){error.innerHTML='<div class="error">فقط یک عنوان در یک خط، حداکثر ۲۵۰ کاراکتر وارد کنید</div>';return;}if(textAssistant.target==='caption'){setCaptionBody(value);}else if(textAssistant.target==='description'){descriptionEditor.set(value);}else{input.value=value;input.dispatchEvent(new Event('input',{bubbles:true}));}modalRoot.innerHTML='';textAssistant=null;toast('پیشنهاد روی بخش انتخاب شده اعمال شد؛ متن همچنان قابل ویرایش دستی است');}
function networkLabel(channel){const detail=channel.access_detail;if(!channel.tokenConfigured||!channel.target)return 'تنظیمات ناقص';if(detail?.checks?.network==='failed')return 'خطای دسترسی شبکه';if(detail?.checks?.token==='failed')return 'توکن نامعتبر';if(detail?.checks?.channel==='failed')return 'کانال در دسترس نیست';if(detail?.checks?.posting==='failed')return 'مجوز ارسال ندارد';if(detail?.ok)return 'اتصال و مجوز تایید شد';if(detail?.checks?.token==='passed')return 'بررسی بخشی تایید شد';return 'نیازمند بررسی اتصال';}
