const effortLabels={none:'None — بدون استدلال',minimal:'Minimal — حداقلی',low:'Low — کم',medium:'Medium — متوسط',high:'High — زیاد',xhigh:'Extra high — خیلی زیاد',max:'Max — حداکثر'};
