function aiView(){
 const ai=state.ai||{},selected=aiModels.find(model=>model.id===ai.model)||aiModels[0],choice=ai.effortsByModel?.[selected?.id||ai.model]??selected?.defaultEffort;
 return '<section class="panel brand-settings-section settings-ai" aria-labelledby="ai-settings-title"><div class="panel-head"><h3 id="ai-settings-title">هوش مصنوعی</h3><span class="tag '+(ai.canGenerate?'green':'')+'">'+(ai.canGenerate?'مجوز تولید متن فعال':ai.connected?'مجوز مصرف سهمیه داده نشده':'متصل نشده')+'</span></div><div class="panel-body"><p class="help">این حساب فقط برای کمک به نوشتن متن پست استفاده می شود مصرف از سهمیه همین حساب کم می شود؛ هر پیشنهاد پیش از اعمال قابل بازبینی است</p>'+(ai.profile?'<p><bdi>'+esc(ai.profile.email||ai.profile.name)+'</bdi></p>':'')+'<div class="checks"><button type="button" class="button chatgpt-signin" data-action="ai-connect" '+(!state.capabilities?.chatgptConnect?'disabled':'')+'>Continue with ChatGPT</button>'+(ai.connected?'<button type="button" class="button secondary" data-action="ai-disconnect">قطع اتصال حساب</button>':'')+(editor?'<button type="button" class="button secondary" data-action="ai-resume-editor">ادامه ویرایش پست</button>':'')+'</div><p id="ai-connection-message" class="help"></p>'+(ai.canGenerate?'<hr><div class="form-grid"><label class="field"><span>مدل تولید متن</span><select id="ai-model" aria-label="مدل تولید متن" '+(!aiModels.length?'disabled':'')+'>'+(aiModels.length?aiModels.map(model=>'<option value="'+esc(model.id)+'" '+(selected?.id===model.id?'selected':'')+'>'+esc(model.name)+'</option>').join(''):'<option>'+(ai.model?esc(ai.model):'ابتدا مدل های حساب را دریافت کنید')+'</option>')+'</select></label><label class="field"><span>میزان تلاش مدل</span><select id="ai-effort" aria-label="میزان تلاش مدل" '+(!selected?'disabled':'')+'>'+effortOptions(selected,choice)+'</select></label></div><p class="help">Low معمولا برای عنوان و بازنویسی متن مناسب است تلاش بیشتر معمولا زمان و مصرف بیشتری دارد؛ این گزینه سقف دقیق توکن تعیین نمی کند گزینه های فعال متناسب با مدل هستند</p><p class="help">Ultra در فهرست حساب به اجرای چندعاملی اشاره دارد؛ اتصال مستقیم این پنل آن را اجرا نمی کند</p><div class="checks"><button type="button" class="button secondary small" data-action="ai-models">دریافت مدل های حساب</button><button type="button" class="button small" data-action="ai-save-model" '+(!aiModels.length?'disabled':'')+'>ذخیره مدل و میزان تلاش</button></div>':'')+'<p class="help">حساب و انتخاب هر عضو مستقل است اتصال فعلی برای اجرای محلی روی همین دستگاه آماده است</p></div></section>';
}
function workspaceSettingsView(){return '<section class="panel workspace-settings" aria-labelledby="workspace-settings-title"><div class="panel-head"><h2 id="workspace-settings-title">مدیریت برندها</h2></div><div class="panel-body">'+(state.capabilities?.needsBrand?'<p class="form-note">'+(state.capabilities.canCreateBrands?'برای شروع اولین برند خود را بسازید سپس اطلاعات برند، کانال ها و هوش مصنوعی را تنظیم کنید':'هنوز به برندی دسترسی ندارید از مدیر برند بخواهید حساب شما را به اعضای تیم اضافه کند')+'</p>':'')+workspaceSelector()+'<p class="help">با تغییر برند، محتوا، کانال ها، اعضا و اتصال هوش مصنوعی همان برند نمایش داده میشود نیازی به ورود دوباره نیست</p>'+(admin()?settingsView():'')+'</div></section>';}
function accountSettingsView(){return accountMarkup(state.account,state.verification||bootstrap.registration,{field,esc,icon});}
function updateAccount(account){state.account=account;const section=document.querySelector('.account-settings');if(section)section.outerHTML=accountSettingsView();}
function brandLogo(){const id=state.settings.brandLogoId;return '<span class="brand-mark '+(id?'has-logo':'')+'" aria-hidden="true">'+(id?'<img src="/media/'+esc(id)+'" alt="" width="43" height="43">':icon('posts'))+'</span>';}
function logoSettingsView(){return '<section class="brand-logo-settings full"><div id="brand-logo-preview">'+brandLogo()+'</div><div class="brand-logo-content"><strong>لوگوی برند</strong><p class="help">تصویر PNG، JPG یا WebP تا ۲ مگابایت؛ لوگو برای همین برند ذخیره میشود</p><div class="brand-logo-actions"><label class="button secondary small logo-file-label">انتخاب یا تغییر لوگو<input type="file" id="brand-logo-file" accept="image/png,image/jpeg,image/webp"></label><button class="button ghost small" data-action="remove-brand-logo" type="button" '+(!state.settings.brandLogoId?'hidden':'')+'>حذف لوگو</button></div><p class="help">تغییر لوگو بلافاصله ذخیره میشود</p><div id="brand-logo-error" role="status"></div></div></section>';}
function updateBrandLogo(id){state.settings.brandLogoId=id;document.querySelector('.sidebar .brand-mark').outerHTML=brandLogo();const preview=document.querySelector('#brand-logo-preview'),remove=document.querySelector('[data-action="remove-brand-logo"]');if(preview)preview.innerHTML=brandLogo();if(remove)remove.hidden=!id;}
function bindBrandLogo(){document.querySelector('#brand-logo-file')?.addEventListener('change',async event=>{
 const input=event.target,file=input.files[0];if(!file)return;if(mediaUploadInFlight)return;const box=document.querySelector('#brand-logo-error');box.textContent='';
 if(file.size>2*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type)){box.textContent='تصویر PNG، JPG یا WebP تا ۲ مگابایت انتخاب کنید';input.value='';return;}
 mediaUploadInFlight=true;input.disabled=true;document.querySelector('[data-action="remove-brand-logo"]').disabled=true;
 try{const form=new FormData();form.set('file',file);const result=await api('/api/brand/logo',{method:'POST',body:form});updateBrandLogo(result.media.id);toast('لوگوی همین برند ذخیره شد');}catch(error){box.textContent=error.message;}finally{mediaUploadInFlight=false;input.disabled=false;input.value='';const remove=document.querySelector('[data-action="remove-brand-logo"]');if(remove)remove.disabled=false;}
 });}
function settingsView(){
 const s=state.settings;
 return `<form id="settings-form" class="brand-settings-form">
 <section class="panel brand-settings-section brand-identity" aria-labelledby="brand-identity-title"><div class="panel-head"><h3 id="brand-identity-title">هویت برند</h3></div><div class="panel-body"><div class="form-grid">${logoSettingsView()}<section class="brand-name-settings full" aria-labelledby="brand-name-title"><div class="panel-head"><h3 id="brand-name-title">نام برند</h3></div><div class="panel-body"><label class="field"><input name="brand" aria-labelledby="brand-name-title" maxlength="120" value="${esc(s.brand||state.workspace.name)}" placeholder="نام برند یا شرکت"></label><p class="help">نام برند فعال در سایدبار و فهرست برندها به روز میشود تغییر نام با دکمه ذخیره تنظیمات برند ثبت میشود</p></div></section></div></div></section>
 <section class="panel brand-settings-section" aria-labelledby="brand-contacts-title"><div class="panel-head"><h3 id="brand-contacts-title">اطلاعات ثابت و راه های ارتباطی</h3></div><div class="panel-body"><div class="form-grid"><label class="field full"><span>واحد قیمت</span><select name="currency"><option ${s.currency==='تومان'?'selected':''}>تومان</option><option ${s.currency==='ریال'?'selected':''}>ریال</option><option ${s.currency==='دلار'?'selected':''}>دلار</option></select></label>${contactsEditor(defaultContacts())}${field('website','آدرس وب سایت',s.website,{type:'url',ltr:true,full:true,placeholder:'https://example.com'})}</div></div></section>
 <section class="panel brand-settings-section brand-time-settings" aria-labelledby="brand-time-title"><div class="panel-head"><h3 id="brand-time-title">تاریخ و ساعت</h3></div><div class="panel-body"><label class="field"><span>منطقه زمانی برند</span><select name="timezone" aria-label="منطقه زمانی برند">${timeZones(activeTimeZone()).map(zone=>'<option value="'+esc(zone)+'" '+(zone===activeTimeZone()?'selected':'')+'>'+esc(zoneLabel(zone))+' · '+esc(zone)+'</option>').join('')}</select></label><p class="help">تقویم، ساعت های پنل و زمان وارد شده برای انتشار با این منطقه زمانی نمایش داده میشوند زمان پست های قبلی تغییر نمیکند</p></div></section>
 <section class="panel brand-settings-section"><div class="panel-head"><h3>آمار کلیک لینک</h3></div><div class="panel-body"><label class="check-row"><input type="checkbox" name="trackingEnabled" ${s.trackingEnabled?'checked':''} ${!state.tracking?.available?'disabled':''}>آمار کلیک لینک برای برند فعال باشد</label><p class="help">${esc(state.tracking?.reason||'بعد از فعال شدن، میتوانید آمار کلیک را برای هر پیام جدا انتخاب کنید')} این آمار با بازدید خود پیام فرق دارد و فقط لینک های بعد از فعال شدن قابل اندازه گیری هستند</p></div></section>
  <div class="brand-save-actions"><div id="settings-error" role="status"></div><button type="submit" class="button">${icon('check')}ذخیره تنظیمات برند</button></div></form>`;
}
function channelSettingsView(){return `<section class="panel brand-settings-section settings-channels" aria-labelledby="settings-channels-title"><div class="panel-head"><h3 id="settings-channels-title">کانال ها</h3></div><div class="panel-body">${channelsView()}</div></section>`;}
function connectionSettingsView(){return `<section class="panel brand-connections" aria-labelledby="brand-connections-title"><div class="panel-head"><h2 id="brand-connections-title">تنظیمات اتصال</h2></div><div class="panel-body"><p class="help">تنظیمات این بخش مربوط به برند فعال است هر پیامرسان جداگانه ذخیره و بررسی میشود اتصال هوش مصنوعی هر عضو هم برای همین برند نگهداری میشود</p>${channelSettingsView()}${editable()?aiView():''}</div></section>`;}
function accessSettingsView(){return `<section class="panel settings-access" aria-labelledby="settings-access-title"><div class="panel-head"><h2 id="settings-access-title">دسترسی</h2></div><div class="panel-body"><p class="help">اعضا، نقش ها و تاریخچه فعالیت مربوط به برند فعال هستند رویدادها بر اساس دسترسی حساب شما نمایش داده میشوند</p>${admin()?`<section class="panel brand-settings-section settings-team" aria-labelledby="settings-team-title"><div class="panel-head"><h3 id="settings-team-title">اعضای تیم</h3></div><div class="panel-body"><div id="team-members-list">${state.users?teamMembersView(state.users):'<div class="skeleton">در حال دریافت اعضای تیم…</div>'}</div></div></section>`:''}${activityView()}</div></section>`;}
function replaceSettingsSection(selector,markup){const section=document.querySelector(selector);if(section)section.outerHTML=markup;}
function updateAiSettings(){if(current==='settings'&&editable())replaceSettingsSection('.settings-ai',aiView());}
function updateChannelSettings(channelId){
 if(current!=='settings')return;const selector='[data-channel-card="'+channelId+'"]',card=document.querySelector(selector);
 const template=document.createElement('template');template.innerHTML=channelsView();const replacement=template.content.querySelector(selector);if(replacement){if(card)card.replaceWith(replacement);else document.querySelector('.channel-cards')?.append(replacement);bindChannels(replacement);}else card?.remove();
}
function updateBrandSettings(){
 if(current!=='settings')return;replaceSettingsSection('.workspace-settings',workspaceSettingsView());bindWorkspacePicker();bindBrandLogo();
 document.title=projectName()+' | مدیریت انتشار';const name=activeBrandName(),sidebar=document.querySelector('.active-brand-name');if(sidebar){sidebar.textContent=name;sidebar.title=name;}const eyebrow=document.querySelector('.eyebrow');if(eyebrow)eyebrow.textContent=name;
}
function dashboardReports(){const totals=state.librarySummary||librarySummary(state.posts);return `<section class="panel section-gap dashboard-reports" aria-labelledby="dashboard-reports-title"><div class="panel-head"><h2 id="dashboard-reports-title">گزارش محتوا</h2><a class="button secondary small" href="/api/export">دریافت CSV</a></div><div class="panel-body"><div class="report-types">${Object.entries(typeNames).map(([type,name])=>`<div class="report-type">${icon({stock:'box',proof:'camera',prices:'list',blog:'book',free:'posts'}[type])}<strong>${number(totals.types[type]||0)}</strong><span>${name}</span></div>`).join('')}</div><div class="missing-metric"><span>محتواهای بایگانی شده</span><strong>${number(totals.archived)}</strong></div><p class="help">تعداد هر نوع محتوا فقط شامل محتوای فعال است و موارد بایگانی و حذف شده را شامل نمیشود آمار آماده انتشار، پیش نویس و ارسال ها در بالای داشبورد نمایش داده می شود</p><details class="audience-report"><summary>آمار عملکرد مخاطب <span class="tag amber">هنوز متصل نشده</span></summary><div>${['بازدید پست ها','کلیک لینک ها','استعلام خرید مرتبط','سفارش منتسب به محتوا'].map(label=>`<div class="missing-metric"><span>${label}</span><span>ناموجود</span></div>`).join('')}<p class="help">این داده ها پس از اتصال رهگیری و منبع آمار نمایش داده می شوند داده ناموجود صفر محسوب نمی شود</p></div></details></div></section>`;}
function activityView(){return `<section class="panel brand-settings-section settings-activity" aria-labelledby="settings-activity-title"><div class="panel-head"><h3 id="settings-activity-title">تاریخچه تغییرات</h3><span class="tiny">آخرین رویدادها</span></div>${state.audit.length?`<ul class="audit-list">${state.audit.map(a=>`<li>${esc(actions[a.action]||a.action)}<small>${esc(a.actor_name||'سیستم')} · ${date(a.created_at)}${a.detail.title?' · '+esc(a.detail.title):''}</small></li>`).join('')}</ul>`:empty('هنوز رویدادی ثبت نشده','فعالیت ها پس از انجام در این بخش نمایش داده می شوند',false)}</section>`;}
function teamMembersView(users){return `<div class="settings-team-actions"><button class="button small" data-action="add-user">${icon('plus')}عضو جدید</button></div><div class="table-wrap"><table class="users-table"><thead><tr><th>نام و حساب</th><th>نقش</th><th>کانال های مجاز</th><th>وضعیت</th><th>مدیریت</th></tr></thead><tbody>${users.map(user=>`<tr><td>${esc(user.name)}<br><bdi class="tiny">${esc(user.username)}</bdi></td><td>${roleNames[user.role]}</td><td>${user.channels.map(id=>esc(destinationName(id))).join('، ')}</td><td><span class="tag ${user.active?'green':''}">${user.active?'فعال':'غیرفعال'}</span></td><td><button class="button secondary small" data-action="edit-user" data-id="${user.id}">ویرایش دسترسی</button></td></tr>`).join('')}</tbody></table></div><p class="help">تولیدکننده محتوای خودش را ویرایش می کند مسوول انتشار می تواند محتوا را برای صف تایید کند مشاهده گر فقط اطلاعات کانال های مجاز را می بیند</p>`;}
async function loadUsers(){
 const box=document.querySelector('#team-members-list');if(!admin()||!box)return;const scope=settingsScope();
 try{const {users}=await api('/api/users');if(scope!==settingsScope()||!box.isConnected||current!=='settings')return;state.users=users;box.innerHTML=teamMembersView(users);}
 catch(error){if(scope===settingsScope()&&box.isConnected){box.innerHTML='<div class="error">'+esc(error.message)+'</div><button type="button" class="button secondary small" data-action="reload-users">دریافت دوباره اعضا</button>';}}
}
function userModal(user){modalRoot.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="user-title"><h2 id="user-title">${user?'ویرایش دسترسی عضو':'افزودن عضو تیم'}</h2><form id="user-form" data-id="${user?.id||''}"><div class="form-grid">${field('name','نام نمایشی',user?.name||'',{required:true})}${user?'':field('username','شناسه حساب اصلی عضو','',{required:true,ltr:true,hint:'نام کاربری یا ایمیل و موبایل تایید شده عضو'})}${user?'':field('password','رمز اولیه عضو جدید (اختیاری)','',{type:'password',hint:'اگر عضو حساب اصلی دارد خالی بگذارید؛ برای حساب جدید حداقل ۱۲ کاراکتر',full:true})}<label class="field full"><span>نقش</span><select name="role">${Object.entries(roleNames).map(([role,name])=>`<option value="${role}" ${(user?.role||'editor')===role?'selected':''}>${name}</option>`).join('')}</select></label></div><h3 class="form-section">کانال های مجاز</h3>${channelChecks(user?.channels||state.channels.map(c=>c.id))}${user?`<label class="check-row"><input name="active" type="checkbox" ${user.active?'checked':''}>دسترسی به این برند فعال باشد</label>`:''}<div id="user-error"></div><div class="modal-actions"><button class="button" type="submit">ذخیره عضو</button><button class="button secondary" type="button" data-action="close-modal">انصراف</button></div></form></div>`;modalRoot.querySelector('input')?.focus();}
function resetRoute(){return location.hash==='#reset'||location.hash.startsWith('#reset=');}
function authView(){editorDates?.destroy();editorDates=null;settingsAccordions?.destroy();settingsAccordions=null;previewLayout?.destroy();previewLayout=null;if(!state)guidance.deactivate();workspacePicker?.destroy();workspacePicker=null;navigation?.destroy();navigation=null;document.title='محتوان | حساب کاربری';root.innerHTML=authMarkup({mode:authMode,registration:bootstrap.registration,remembered:bootstrap.remembered,username:loginUsername,challenge:verificationChallenge,resetForm:authMode==='reset'?resetForm():''},{field,esc,icon});scheduleResend();}
function scheduleResend(){clearTimeout(resendTimer);const button=document.querySelector('[data-action="resend-code"]');if(button&&verificationChallenge){const remaining=Date.parse(verificationChallenge.resendAt)-Date.now();button.disabled=remaining>0;if(remaining>0)resendTimer=setTimeout(()=>{if(button.isConnected)button.disabled=false;},remaining+50);}}
function contactVerification(challenge){verificationChallenge=challenge;modalRoot.innerHTML='<div class="modal" role="dialog" aria-modal="true" aria-labelledby="contact-verify-title"><h2 id="contact-verify-title">تایید راه ارتباطی</h2><form id="contact-verify-form">'+verificationFields(challenge,esc)+'<div data-form-error></div><div class="modal-actions"><button class="button" type="submit">تایید کد</button><button class="button secondary" type="button" data-action="close-modal">انصراف</button></div></form>'+resendButton(challenge)+'</div>';scheduleResend();modalRoot.querySelector('input').focus();}
function resetForm(){return '<form id="reset-form">'+(!recoveryToken?field('token','لینک یا کد بازیابی','',{required:true,ltr:true,hint:'لینک را از مدیر سرویس بگیرید در نصب محلی، فایل Reset-Password.ps1 را روی همین کامپیوتر اجرا کنید'}):'<div class="form-note">لینک بازیابی دریافت شد رمز جدید را در فرم زیر وارد کنید</div>')+field('password','رمز جدید','',{type:'password',required:true,hint:'حداقل ۱۲ کاراکتر'})+field('confirmation','تکرار رمز جدید','',{type:'password',required:true})+'<div id="reset-error"></div><button class="button" type="submit">ذخیره رمز جدید</button></form><button type="button" class="auth-link" data-action="back-login">بازگشت</button><p class="help">لینک یک بارمصرف و ۲۰ دقیقه معتبر است این لینک را فقط در فرم بازیابی خودتان وارد کنید</p>';}
function passwordModal(){modalRoot.innerHTML='<div class="modal" role="dialog" aria-modal="true" aria-labelledby="password-title"><h2 id="password-title">تغییر رمز حساب من</h2><form id="password-form">'+field('currentPassword','رمز فعلی','',{type:'password',required:true,autocomplete:'current-password'})+field('password','رمز جدید','',{type:'password',required:true,hint:'حداقل ۱۲ کاراکتر'})+field('confirmation','تکرار رمز جدید','',{type:'password',required:true})+'<div id="password-error"></div><div class="modal-actions"><button class="button" type="submit">ذخیره رمز جدید</button><button class="button secondary" type="button" data-action="close-modal">انصراف</button></div><button class="auth-link" type="button" data-action="forgot">رمز فعلی را فراموش کرده ام</button></form></div>';modalRoot.querySelector('input').focus();}
function tokenFromValue(value){const raw=String(value||'').trim();if(raw.startsWith('http://')||raw.startsWith('https://')){try{return new URLSearchParams(new URL(raw).hash.slice(1)).get('reset')||'';}catch{return '';}}return raw;}
async function init(){bootstrap=await api('/api/bootstrap');if(resetRoute()){recoveryToken=new URLSearchParams(location.hash.slice(1)).get('reset')||'';authMode='reset';authView();return;}if(!bootstrap.user){state=null;authView();return;}authMode='login';await refresh();try{const resume=JSON.parse(sessionStorage.getItem('desk:ai-editor')||'null');if(!editor&&resume?.userId===state.user.id&&resume.workspaceId===state.workspace.id&&resume.editor)editor=resume.editor;sessionStorage.removeItem('desk:ai-editor');}catch{}current=workspaceView();navExpanded=current==='editor'?'posts':['posts','settings'].includes(current)?current:'';if(current==='editor'&&!editor)editor=newEditor();shell();}

function closeModal(){
 if(libraryActionInFlight)return;
 const dialog=modalRoot.firstElementChild;if(!dialog||dialog.classList.contains('is-closing'))return;copyRequest=null;
 if(matchMedia('(prefers-reduced-motion: reduce)').matches||!dialog.animate){modalRoot.replaceChildren();return;}
 dialog.classList.add('is-closing');dialog.inert=true;
 const style=getComputedStyle(dialog),exit=dialog.animate([{opacity:style.opacity,transform:style.transform},{opacity:0,transform:'translateY(5px) scale(.99)'}],{duration:120,easing:'ease-in',fill:'forwards'});
 const finish=()=>{if(modalRoot.firstElementChild===dialog)modalRoot.replaceChildren();};exit.finished.then(finish,finish);
}
function newWorkspaceModal(){
 if(current==='editor'&&editor&&document.querySelector('#editor-form'))editor={...editor,...collectEditor()};
 modalRoot.innerHTML='<div class="modal" role="dialog" aria-modal="true" aria-labelledby="workspace-title"><h2 id="workspace-title">افزودن برند یا شرکت</h2><p class="help">کانال ها، توکن ها، فایل ها، محتوا و اعضای برند جدید مستقل خواهند بود</p><form id="workspace-form">'+field('name','نام برند یا شرکت','',{required:true,placeholder:'مثلا شرکت شبکه آریا'})+'<p class="form-note">برند به همین حساب اصلی اضافه میشود رمز شما برای همه برندها مشترک است؛ هیچ کانال یا محتوایی کپی نمیشود</p><div id="workspace-error"></div><div class="modal-actions"><button class="button" type="submit">ساخت برند مستقل</button><button class="button secondary" type="button" data-action="close-modal">انصراف</button></div></form></div>';modalRoot.querySelector('input').focus();
}
function workspaceHasUnsavedChanges(){return !!(current==='editor'&&editor)||[...document.querySelectorAll('#view input,#view textarea,#view select')].some(input=>input.tagName==='SELECT'?[...input.options].some(option=>option.selected!==option.defaultSelected):['checkbox','radio'].includes(input.type)?input.checked!==input.defaultChecked:input.value!==input.defaultValue);}
async function resetWorkspaceUi(){selectedPosts.clear();libraryRequest=null;contentCalendar?.destroy();contentCalendar=null;calendarState=null;state=null;bootstrap=null;editor=null;descriptionEditor=null;textAssistant=null;aiModels=[];search='';filter='all';expandedChannel=null;modalRoot.replaceChildren();sessionStorage.removeItem('desk:ai-editor');authMode='login';current='settings';history.replaceState(null,'','#settings');await init();}
async function switchWorkspace(id){
 if(id===state.workspace.id)return;
 const picker=document.querySelector('#workspace-picker');
 if(editorSubmitInFlight||publishingInFlight||mediaUploadInFlight){picker.value=state.workspace.id;toast('ابتدا منتظر پایان ذخیره، ارسال یا بارگذاری بمانید');return;}
 if(workspaceHasUnsavedChanges()&&!confirm('تغییرات ذخیره نشده با خروج از این برند از دست می رود ادامه می دهید؟')){picker.value=state.workspace.id;return;}
 picker.disabled=true;
 try{await api('/api/workspaces/select',{method:'POST',body:{id}});await resetWorkspaceUi();}catch(error){picker.disabled=false;if(state)picker.value=state.workspace.id;toast(error.message);}
}
document.addEventListener('click',async event=>{if(libraryActionInFlight)return;if(event.target===modalRoot){closeModal();return;}const button=event.target.closest('[data-action]');if(!button){
 const row=event.target.closest('#post-list .content-row'),input=row?.querySelector('[data-select-post]');
 if(current==='posts'&&input&&!input.disabled&&!event.defaultPrevented&&!event.target.closest('button,a,input,label,select,textarea,summary,[contenteditable],[role="button"],[role="link"]')&&window.getSelection()?.isCollapsed!==false&&canManageLibrary(state.posts.find(post=>post.id===input.dataset.selectPost),state.user))input.click();
 return;
}const action=button.dataset.action;
 if(editorSubmitInFlight&&['nav','create','inspect','type','ai-open','add-workspace','default-workspace'].includes(action)){toast('ذخیره یا انتشار در حال انجام است؛ منتظر نتیجه بمانید');return;}
 try{
   if(action==='add-workspace'){newWorkspaceModal();return;}
   if(action==='default-workspace'){button.disabled=true;await api('/api/workspaces/default',{method:'POST',body:{}});await resetWorkspaceUi();return;}
   if(action==='add-phone'){const box=button.closest('[data-contact-editor]');box.querySelector('[data-phone-list]').insertAdjacentHTML('beforeend',phoneRow());box.querySelector('.phone-row:last-child [data-phone-number]').focus();button.closest('form').dispatchEvent(new Event('input',{bubbles:true}));return;}
   if(action==='remove-phone'){const form=button.closest('form');button.closest('.phone-row').remove();form.dispatchEvent(new Event('input',{bubbles:true}));return;}
   if(action==='reset-contacts'){const form=button.closest('form');button.closest('[data-contact-editor]').outerHTML=contactsEditor(defaultContacts(),true);form.dispatchEvent(new Event('input',{bubbles:true}));return;}
   if(action==='ai-open'){modalRoot.innerHTML='';navigate('ai');return;}
   if(action==='ai-connect'){
     button.disabled=true;
     try{const result=await api('/api/ai/connect',{method:'POST',body:{}});if(editor)sessionStorage.setItem('desk:ai-editor',JSON.stringify({userId:state.user.id,workspaceId:state.workspace.id,editor}));const box=document.querySelector('#ai-connection-message');box.innerHTML='<a href="'+esc(result.url)+'" rel="noreferrer">ادامه ورود در صفحه رسمی OpenAI</a>';location.assign(result.url);}
     finally{button.disabled=false;}return;
   }
   if(action==='ai-resume-editor'){navigate('editor');return;}
   if(action==='ai-disconnect'){const scope=settingsScope();button.disabled=true;const result=await api('/api/ai/disconnect',{method:'POST',body:{}});if(scope!==settingsScope())return;aiModels=[];await refresh();if(scope===settingsScope()){updateAiSettings();toast(result.message);}return;}
   if(action==='ai-models'){const scope=settingsScope();button.disabled=true;try{const result=await api('/api/ai/models');if(scope!==settingsScope())return;aiModels=result.models;await refresh();if(scope===settingsScope())updateAiSettings();}finally{if(button.isConnected)button.disabled=false;}return;}
   if(action==='ai-save-model'){const scope=settingsScope();button.disabled=true;try{await api('/api/ai/model',{method:'POST',body:{model:document.querySelector('#ai-model').value,effort:document.querySelector('#ai-effort').value}});if(scope!==settingsScope())return;await refresh();if(scope===settingsScope()){updateAiSettings();toast('مدل و میزان تلاش ذخیره شد');}}finally{if(button.isConnected)button.disabled=false;}return;}
   if(action==='assist-generate'){
     const data=collectEditor(),assistant=textAssistant;button.disabled=true;
     try{const result=await api('/api/text-assist/generate',{method:'POST',body:{...data,target:assistant.target,current:targetInput(assistant.target).value,intent:document.querySelector('#assist-intent').value,instructions:document.querySelector('#assist-instructions').value}});if(textAssistant===assistant&&document.querySelector('#assist-result')){document.querySelector('#assist-result').value=result.text;toast('پیشنهاد آماده است؛ پیش از اعمال، آن را بررسی کنید');}}
     catch(error){const errorBox=document.querySelector('#assist-error');if(errorBox)errorBox.innerHTML='<div class="error">'+esc(plainUi(error.message))+'</div>';else toast(error.message);}finally{if(button.isConnected)button.disabled=false;}return;
   }
   if(action==='rename-post'){renamePostModal(state.posts.find(p=>p.id===button.dataset.id));return;}
   if(action==='library-copy'){copyPostModal(state.posts.filter(post=>selectedPosts.has(post.id)));return;}
   if(action==='copy-post'){const post=state.posts.find(p=>p.id===button.dataset.id);if(canCopyPost(post))copyPostModal(post);return;}
   if(action==='remote-controls'){const scope=settingsScope(),post=state.posts.find(p=>p.id===button.dataset.id)||await api('/api/posts/'+button.dataset.id).then(result=>result.post);await openMessageControls({post,writable:publisher(),api,modalRoot,esc,number,platformLogo,setBusy:value=>libraryActionInFlight=value,isCurrent:()=>scope===settingsScope(),onChange:refresh});return;}
   if(action==='publication-results'){await showPublicationResults(button.dataset.id);return;}
   if(action==='publish-post'){const post=state.posts.find(p=>p.id===button.dataset.id);button.disabled=true;await publishSavedPost(post.id,post.version);return;}
   if(action==='password'){passwordModal();return;}
   if(action==='forgot'){modalRoot.innerHTML='';recoveryToken='';authMode='forgot';authView();return;}
   if(action==='register'){authMode='register';verificationChallenge=null;authView();return;}
   if(action==='host-recovery'){authMode='reset';authView();return;}
   if(action==='resend-code'){button.disabled=true;try{const result=await api('/api/accounts/resend',{method:'POST',body:{challengeId:verificationChallenge.challengeId}});verificationChallenge=result;if(result.purpose==='contact')contactVerification(result);else authView();toast('کد جدید ارسال شد');}finally{if(button.isConnected)button.disabled=Date.now()<Date.parse(verificationChallenge.resendAt);}return;}
   if(action==='remove-brand-logo'){if(mediaUploadInFlight)return;button.disabled=true;try{await api('/api/brand/logo',{method:'DELETE',body:{}});updateBrandLogo('');toast('لوگوی برند حذف شد');}finally{button.disabled=false;}return;}
   if(action==='password-login'){authMode='password-login';authView();return;}
   if(action==='forget-login'){button.disabled=true;await api('/api/auth/remember/forget',{method:'POST',body:{},headers:{'X-CSRF-Token':bootstrap.remembered?.csrf||''}});loginUsername='';authMode='login';await init();return;}
   if(action==='back-login'){authMode='login';verificationChallenge=null;recoveryToken='';if(resetRoute())history.replaceState(null,'',location.pathname+location.search);if(state)shell();else authView();return;}
   if(action==='toggle-nav'){navigation?.toggle();return;}
   if(action==='close-subnav'){navigation?.setOpen(false);return;}
   if(action==='toggle-subnav'){navigation?.toggleSubmenu(button.dataset.group);return;}
   if(action==='nav'){if(button.closest('.sidebar')){const view=button.dataset.view;navExpanded=view.startsWith('posts')?'posts':view.startsWith('settings')?'settings':'';if(view.startsWith('posts')){search='';selectedPosts.clear();}await navigation?.setOpen(false);}navigate(button.dataset.view);return;}
   if(action==='logout'){selectedPosts.clear();libraryRequest=null;await api('/api/logout',{method:'POST',body:{}});guidance.clearSession();state=null;aiModels=[];authMode='login';verificationChallenge=null;history.replaceState(null,'',location.pathname+location.search);await init();return;}
   if(action==='jump-preview'){document.querySelector('.preview').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});document.querySelector('.preview-scroll').focus({preventScroll:true});return;}
   if(action==='jump-editor'){document.querySelector('#editor-form').scrollIntoView({behavior:'smooth',block:'start'});return;}
   if(action==='rebuild-caption'){editor=rebuildComposer(editor,collectEditor(),state.settings);updateMediaPreview();return;}
   if(action==='undo-caption'){editor=undoComposer(editor);updateMediaPreview();return;}
   if(action==='add-destination'){modalRoot.innerHTML='<div class="modal" role="dialog" aria-modal="true" aria-labelledby="destination-title"><h2 id="destination-title">افزودن کانال مقصد</h2><form id="destination-form"><label class="field"><span>پیامرسان</span><select name="platform">'+['telegram','bale','rubika','eitaa'].map(id=>'<option value="'+id+'">'+platformNames[id]+'</option>').join('')+'</select></label>'+field('name','نام نمایشی کانال','',{required:true})+'<div data-form-error></div><div class="modal-actions"><button type="submit" class="button">افزودن</button><button type="button" class="button secondary" data-action="close-modal">انصراف</button></div></form></div>';return;}
   if(action==='remove-destination'){if(!confirm('اتصال این مقصد از پنل حذف شود؟ پیام های کانال و تاریخچه ارسال حفظ میشوند صف مرتبط به تایید دوباره نیاز خواهد داشت'))return;await api('/api/channels/'+button.dataset.id,{method:'DELETE'});await refresh();updateChannelSettings(button.dataset.id);toast('اتصال حذف شد تاریخچه ارسال حفظ شده است');return;}
   if(action==='create'){if(button.closest('.sidebar'))await navigation?.setOpen(false);navExpanded='posts';editor=newEditor();if(current==='editor')shell();else navigate('editor');return;}
   if(action==='filter'){const key=button.dataset.filter;selectedPosts.clear();filter=filter===key?'all':key;navExpanded='posts';history.pushState(null,'','#posts/'+filter);shell();document.querySelector('[data-action="filter"][data-filter="'+key+'"]')?.focus({preventScroll:true});return;}
   if(action==='clear-selection'){selectedPosts.clear();updateBulkSelection();return;}
   if(['library-delete','library-archive','library-restore'].includes(action)){openLibraryAction(action.slice(8),button.dataset.id?[button.dataset.id]:[...selectedPosts]);return;}
   if(action==='inspect'){await inspectPost(state.posts.find(p=>p.id===button.dataset.id));return;}
   if(action==='edit-post'){modalRoot.replaceChildren();await inspectPost(state.posts.find(p=>p.id===button.dataset.id),{edit:true});return;}
   if(['ready','draft'].includes(action)){const post=state.posts.find(p=>p.id===button.dataset.id);button.disabled=true;const result=await api(`/api/posts/${post.id}/${action}`,{method:'POST',body:{version:post.version}});await refresh();shell();toast(action==='ready'?(result.automatic?'ارسال خودکار برای زمان انتخاب شده ثبت شد':'محتوا وارد صف ارسال دستی شد'):'محتوا به پیش نویس برگشت و ارسال خودکار لغو شد');return;}
   if(action==='text-assist'){openTextAssistant(button.dataset.target,button.dataset.label);return;}
   if(action==='assist-build'||action==='assist-copy'){await prepareTextAssistant(action==='assist-copy');return;}
   if(action==='assist-apply'){applyTextSuggestion();return;}
   if(action==='remove-media'){editor={...editor,...collectEditor()};editor.media=editor.media.filter(id=>id!==button.dataset.id);editor.publication_media_ids=editor.publication_media_ids.filter(id=>id!==button.dataset.id);editor.primary_media_id=editor.publication_media_ids[0]||null;shell();return;}
   if(action==='select-all-media'){editor={...editor,...collectEditor()};editor.publication_media_ids=[...editor.publication_media_ids,...editor.media.filter(id=>!editor.publication_media_ids.includes(id))];editor.primary_media_id=editor.publication_media_ids[0]||null;shell();return;}
   if(action==='move-media'){editor={...editor,...collectEditor()};const ids=editor.publication_media_ids,index=ids.indexOf(button.dataset.id),next=index+Number(button.dataset.direction);if(index>=0&&next>=0&&next<ids.length){[ids[index],ids[next]]=[ids[next],ids[index]];editor.primary_media_id=ids[0];shell();}return;}
   if(action==='reload-users'){await loadUsers();return;}if(action==='add-user'){userModal();return;}if(action==='edit-user'){const user=state.users?.find(u=>u.id===button.dataset.id);if(!user)throw new Error('اطلاعات عضو در دسترس نیست دوباره اعضا را دریافت کنید');userModal(user);return;}
   if(action==='close-modal'){closeModal();return;}
 }catch(error){button.disabled=false;toast(error.message);}
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.matches('#auth-form,#remembered-login-form,#register-form,#verify-form,#forgot-form,#recover-form,#contact-verify-form,[data-account-contact],#reset-form,#password-form,#editor-form,#settings-form,#user-form,#workspace-form,#rename-post-form,#copy-post-form,#library-action-form,#destination-form,[data-channel]'))return;event.preventDefault();if(form.id==='editor-form'&&editorSubmitInFlight)return;if(form.id==='editor-form'&&mediaUploadInFlight){toast('ابتدا منتظر پایان بارگذاری فایل ها بمانید');return;}const publishNow=event.submitter?.dataset.intent==='publish-now',queuePost=event.submitter?.dataset.intent==='queue';if(form.id==='editor-form'){editorSubmitInFlight=true;form.inert=true;document.querySelector('.preview').inert=true;}const submit=event.submitter||form.querySelector('[type=submit]');const submitButtons=[...form.querySelectorAll('[type=submit]')];submitButtons.forEach(button=>button.disabled=true);
 try{
   const data=Object.fromEntries(new FormData(form));
   if(form.id==='destination-form'){const scope=settingsScope(),result=await api('/api/channels',{method:'POST',body:data});if(scope!==settingsScope())return;await refresh();expandedChannel=result.channel.id;modalRoot.innerHTML='';updateChannelSettings(result.channel.id);toast('کانال اضافه شد تنظیمات اتصال آن را وارد کنید');return;}
   if(form.id==='rename-post-form'){await api('/api/posts/'+form.dataset.id+'/library-title',{method:'PUT',body:{title:data.title,version:Number(form.dataset.version),previous:JSON.parse(form.dataset.previous)}});await refresh();modalRoot.innerHTML='';shell();toast('نام داخلی ذخیره شد؛ پیام های کانال ها تغییر نکردند');return;}
   if(form.id==='copy-post-form'){
     if(libraryActionInFlight)return;const request=copyRequest;if(!request||request.scope!==settingsScope())throw new Error('برند فعال تغییر کرده است');
     const channels=new FormData(form).getAll('channels');if(!channels.length)throw new Error('حداقل یک مقصد برای کپی انتخاب کنید');
     libraryActionInFlight=true;form.inert=true;root.inert=true;
     try{
       const result=await api('/api/posts/copies',{method:'POST',body:{posts:request.posts,channels}});if(request.scope!==settingsScope())return;
       await refresh();if(request.scope!==settingsScope())return;selectedPosts.clear();copyRequest=null;modalRoot.replaceChildren();
       if(result.posts.length===1){editor=structuredClone(result.posts[0]);editor.signature=null;if(current==='editor')shell();else navigate('editor');toast('کپی در پیش نویس ذخیره شد؛ پس از بررسی، زمان بندی یا منتشر کنید');}
       else{editor=null;search='';navigate('posts/draft');toast(number(result.count)+' کپی در پیش نویس ها ساخته شد؛ برای بازنشر بررسی و ویرایش کنید');}
     }finally{libraryActionInFlight=false;form.inert=false;root.inert=false;}return;
   }
   if(form.id==='workspace-form'){
    if(mediaUploadInFlight||publishingInFlight)throw Error('منتظر پایان بارگذاری یا ارسال بمانید');
    if(workspaceHasUnsavedChanges()&&!confirm('تغییرات ذخیره نشده با ساخت برند جدید کنار گذاشته میشود ادامه می دهید؟'))return;
    const created=await api('/api/workspaces',{method:'POST',body:{name:data.name}});await api('/api/workspaces/select',{method:'POST',body:{id:created.workspace.id}});await resetWorkspaceUi();toast('برند ساخته و انتخاب شد؛ اطلاعات همین برند را تنظیم کنید');return;
   }
   if(form.id==='register-form'){const result=await api('/api/accounts/register',{method:'POST',body:data});if(result.verificationRequired){verificationChallenge=result;authMode='verify';authView();}else{state=null;await init();toast('حساب ساخته شد؛ راه ارتباطی در نسخه محلی هنوز تایید نشده است');}return;}
   if(form.id==='verify-form'){await api('/api/accounts/verify',{method:'POST',body:{challengeId:verificationChallenge.challengeId,code:data.code}});verificationChallenge=null;state=null;await init();return;}
   if(form.id==='forgot-form'){verificationChallenge=await api('/api/auth/forgot',{method:'POST',body:data});authMode='recover';authView();return;}
   if(form.id==='recover-form'){const result=await api('/api/auth/recover',{method:'POST',body:{...data,challengeId:verificationChallenge.challengeId}});loginUsername=result.username;verificationChallenge=null;state=null;bootstrap=null;authMode='login';await init();toast('رمز حساب اصلی تغییر کرد؛ دوباره وارد شوید');return;}
   if(form.matches('[data-account-contact]')){const result=await api('/api/account/contact',{method:'POST',body:data});if(result.verificationRequired)contactVerification(result);else{updateAccount(result.account);toast('اطلاعات ذخیره شد؛ تایید نشده است');}return;}
   if(form.id==='contact-verify-form'){const result=await api('/api/account/contact/verify',{method:'POST',body:{challengeId:verificationChallenge.challengeId,code:data.code}});updateAccount(result.account);verificationChallenge=null;closeModal();toast('راه ارتباطی تایید شد');return;}
   if(form.id==='reset-form'){const result=await api('/api/auth/reset',{method:'POST',body:{token:recoveryToken||tokenFromValue(data.token),password:data.password,confirmation:data.confirmation}});state=null;editor=null;loginUsername=result.username;recoveryToken='';authMode='login';history.replaceState(null,'',location.pathname+location.search);await init();toast('رمز جدید ذخیره شد با رمز جدید وارد شوید');return;}
   if(form.id==='password-form'){const result=await api('/api/account/password',{method:'POST',body:data});state.csrf=result.csrf;bootstrap.csrf=result.csrf;await refresh();modalRoot.innerHTML='';toast('رمز تغییر کرد؛ نشست های دیگر حساب بسته شدند');return;}
   if(form.id==='remembered-login-form'){await api('/api/login/remembered',{method:'POST',body:{},headers:{'X-CSRF-Token':bootstrap.remembered?.csrf||''}});state=null;await init();return;}
   if(form.id==='auth-form'){await api('/api/login',{method:'POST',body:{...data,remember:data.remember==='on'}});state=null;await init();return;}
   if(form.id==='library-action-form'){
     if(libraryActionInFlight)return;const request=libraryRequest;if(!request||request.scope!==settingsScope())throw new Error('برند فعال تغییر کرده است');libraryActionInFlight=true;form.inert=true;root.inert=true;
     try{const result=await api('/api/posts/library-actions',{method:'POST',body:{action:request.action,posts:request.posts}});if(request.scope!==settingsScope())return;const changed=new Map(result.posts.map(post=>[post.id,post]));state.posts=state.posts.map(post=>changed.has(post.id)?{...post,...changed.get(post.id)}:post);selectedPosts.clear();modalRoot.replaceChildren();libraryRequest=null;if(request.fromEditor){editor=null;current='posts';history.replaceState(null,'','#posts');}shell();toast(number(result.count)+' محتوا '+({delete:'حذف شد؛ از حذف شده ها قابل بازیابی است',archive:'بایگانی شد',restore:'بازگردانی شد'})[request.action]);}finally{libraryActionInFlight=false;form.inert=false;root.inert=false;}return;
   }
   if(form.id==='editor-form'){
     let data=collectEditor();if(queuePost){if(!publisher())throw new Error('دسترسی ارسال به صف را ندارید');if(!data.scheduled_at||!Number.isFinite(Date.parse(data.scheduled_at))||Date.parse(data.scheduled_at)<=Date.now())throw new Error('برای ارسال به صف، زمان انتشار را در آینده مشخص کنید');if(data.expires_at&&Date.parse(data.expires_at)<=Date.parse(data.scheduled_at))throw new Error('اعتبار قیمت باید بعد از زمان انتشار باشد');}const originalId=editor.id;editor=syncComposer(editor,data,state.settings);data={...data,body:editor.body,body_entities:editor.body_entities,body_mode:editor.body_mode,body_source:editor.body_source};
     const saved=await api(originalId?'/api/posts/'+originalId:'/api/posts',{method:originalId?'PUT':'POST',body:data});editor={...editor,...saved.post};const savedId=saved.post.id;if(queuePost){await api('/api/posts/'+savedId+'/ready',{method:'POST',body:{version:saved.post.version}});editor=null;await refresh();editorSubmitInFlight=false;navigate('queue');toast('ارسال خودکار برای زمان انتخاب شده ثبت شد');}else if(publishNow){await publishSavedPost(savedId,saved.post.version);if(editor?.id===savedId){editor=null;editorSubmitInFlight=false;navigate('posts');}}else{editor=null;await refresh();editorSubmitInFlight=false;navigate('posts');toast('پیش نویس ذخیره شد');}return;
   }
   if(form.dataset.channel){const scope=settingsScope(),channelId=form.dataset.channel;form.inert=true;submit.textContent='در حال بررسی اتصال…';try{const result=await saveChannelForm(form);if(scope!==settingsScope())return;await refresh();if(scope===settingsScope()){expandedChannel=channelId;updateChannelSettings(channelId);toast(result.ok?'تنظیمات ذخیره شد؛ ارتباط و مجوز ارسال تایید شدند':'تنظیمات ذخیره شد؛ نتیجه و راهنمای بررسی زیر کانال نمایش داده شد');}}finally{form.inert=false;submit.textContent='ذخیره و بررسی اتصال';}return;}
   if(form.id==='settings-form'){const scope=settingsScope();await api('/api/settings',{method:'PUT',body:{...data,trackingEnabled:form.elements.trackingEnabled.checked,contact:'',contacts:normalizeContacts(collectContacts(form))}});if(scope!==settingsScope())return;await refresh();if(scope===settingsScope()){updateBrandSettings();toast('تنظیمات ذخیره شد');}return;}
   if(form.id==='user-form'){const id=form.dataset.id,scope=settingsScope(),role=state.user.role;await api('/api/users'+(id?'/'+id:''),{method:id?'PUT':'POST',body:{...data,channels:new FormData(form).getAll('channels'),active:id?form.elements.active.checked:true}});if(scope!==settingsScope())return;modalRoot.innerHTML='';await refresh();if(scope===settingsScope()){if(state.user.role!==role)shell();else await loadUsers();toast('اطلاعات عضو ذخیره شد');}return;}
 }catch(error){const target=form.querySelector('[data-form-error],#auth-error,#reset-error,#password-error,#editor-error,#settings-error,#user-error,#workspace-error,#post-action-error');if(target)target.innerHTML=`<div class="error">${esc(plainUi(error.message))}</div>`;else toast(error.message);}finally{if(form.id==='editor-form'){editorSubmitInFlight=false;form.inert=false;const preview=document.querySelector('.preview');if(preview)preview.inert=false;}submitButtons.forEach(button=>{if(button.isConnected)button.disabled=false;});}
});
window.addEventListener('hashchange',async()=>{if(libraryActionInFlight){history.replaceState(null,'',libraryRequest?.route||'#posts');return;}if(editorSubmitInFlight){history.replaceState(null,'','#editor');return;}if(resetRoute()){recoveryToken=new URLSearchParams(location.hash.slice(1)).get('reset')||'';authMode='reset';authView();return;}if(!state){authMode='login';authView();return;}if(current==='settings'&&(location.hash==='#settings'||location.hash.startsWith('#settings/'))){settingsTarget=settingsRoute(location.hash.slice(1));if(settingsTarget==='team'&&!admin())settingsTarget='access';navExpanded='settings';syncSidebar();if(settingsTarget)settingsAccordions?.reveal(settingsTarget);settingsTarget='';return;}try{if(current==='editor'&&editor&&document.querySelector('#editor-form'))editor={...editor,...collectEditor()};await refresh();current=workspaceView();navExpanded=current==='editor'?'posts':['posts','settings'].includes(current)?current:'';if(current==='editor'&&!editor)editor=newEditor();shell();}catch(error){toast(error.message);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeModal();const sidebar=document.querySelector('.sidebar.nav-open');if(sidebar){navigation?.setOpen(false);}}});
init().catch(error=>{root.innerHTML=`<div class="loading">${esc(plainUi(error.message))}</div>`;});

window.addEventListener('focus',async()=>{if(!state||state.capabilities?.needsBrand)return;const scope=settingsScope(),previous=JSON.stringify(state.ai);try{const ai=await api('/api/ai/status');if(scope!==settingsScope())return;state.ai=ai;if(current==='settings'&&JSON.stringify(ai)!==previous)updateAiSettings();}catch{}});
let queueRefreshInFlight=false;
setInterval(async()=>{
 if(current==='calendar'){if(state&&!document.hidden&&!modalRoot.childElementCount)await contentCalendar?.refresh({silent:true});return;}
 if(queueRefreshInFlight||document.hidden||!state||current!=='posts'||modalRoot.childElementCount||publishingInFlight||libraryActionInFlight||editorSubmitInFlight)return;
 const scope=settingsScope(),view=current;queueRefreshInFlight=true;
 try{
  const next=await api('/api/state');
  if(scope!==settingsScope()||view!==current||modalRoot.childElementCount||publishingInFlight||libraryActionInFlight||editorSubmitInFlight||document.activeElement?.closest('#post-list,#library-bulk'))return;
  if(JSON.stringify(next.posts)!==JSON.stringify(state.posts)){
   if(state.users)next.users=state.users;state=next;
   selectedPosts=new Set([...selectedPosts].filter(id=>state.posts.some(post=>post.id===id&&canManageLibrary(post,state.user))));drawLibrary();
  }
 }catch{}finally{queueRefreshInFlight=false;}
},10000);

