document.addEventListener('change',event=>{const input=event.target;if(input.matches('[data-select-post]')){if(input.checked)selectedPosts.add(input.dataset.selectPost);else selectedPosts.delete(input.dataset.selectPost);updateBulkSelection();}else if(input.id==='select-visible-posts'){const focused=document.activeElement===input;selectedPosts=new Set(input.checked?libraryPosts().filter(post=>canManageLibrary(post,state.user)).map(post=>post.id):[]);updateBulkSelection();if(focused)document.querySelector('#select-visible-posts')?.focus({preventScroll:true});}});


